// ***************
// Filename: sdio_host_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of sdio_host: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to sdio_host's logic on named ports, its
//   status comes back on input ports. SD / SDIO host: command, argument,
//   responses, status, clock and bus control, block size, timeout, interrupt
//   enables. Generated by ip/scripts/regmap_gen.py from sdio_host_regs.json:
//   edit the JSON and regenerate (the IP_VERSION / IP_DATE stamps are kept).
//   Register map (ADDR_W = 8, byte offsets):
//     0x00 ID          RO   "SDIO" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x04 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x08 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x0C reserved    RO   0
//     0x10 CMD         RW   a write starts the command; reads back the last
//                       one, reset 0x0
//                       [5:0] INDEX: command index
//                       [7:6] RESP: response: 0 none, 1 short 48 bit, 2 long
//                         136 bit
//                       [9:8] DIR: data: 0 none, 1 read block, 2 write block
//                       [10] NO_CRC: 1: no CRC7 check of the response (R3 /
//                         R7)
//     0x14 ARG         RW   command argument, reset 0x0
//     0x18 + 4 i RESP [4]    RO   response: short in RESP[0], long 127..0 in
//                       RESP[3]..RESP[0]
//     0x28 STATUS      CMD  status; write 1 to clear bits 1-7
//                       [0] BUSY: command or data in progress
//                       [1] CMD_DONE: command finished
//                       [2] DAT_DONE: data block finished
//                       [3] CMD_TIMEOUT: no response
//                       [4] CMD_CRC_ERR: response CRC7 error
//                       [5] DAT_CRC_ERR: data CRC16, end bit or CRC status
//                         error
//                       [6] DAT_TIMEOUT: data or busy timeout
//                       [7] BUF_ERR: bad BLKSIZE, write without a full
//                         buffer, or command while busy
//     0x2C CTRL        RW   SD clock and bus, reset 0x2
//                       [15:0] HALF_PERIOD: SD clock half period in system
//                         clocks (minimum 1)
//                       [16] BUS4: 1: 4-bit data bus
//                       [17] CLK_EN: 1: SD clock running
//     0x30 BLKSIZE     RW   block size in bytes (1..BUF_BYTES), reset 0x200
//     0x34 TIMEOUT     RW   data / busy timeout in SD clocks, reset 0x186A0
//     0x38 IRQ_EN      RW   bit n enables STATUS bit n + 1 for irq_o, reset
//                       0x0
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - aclk.
//   Reset - synchronous active low aresetn. Latency - 2 clocks per write and
//   read.
// Date: 2026-10-12
module sdio_host_regs (
  input  logic                aclk,           // clock
  input  logic                aresetn,        // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  input  logic [7:0]          s_axil_awaddr,  // AXI4-Lite
  input  logic                s_axil_awvalid,
  output logic                s_axil_awready,
  input  logic [31:0]         s_axil_wdata,
  input  logic [3:0]          s_axil_wstrb,
  input  logic                s_axil_wvalid,
  output logic                s_axil_wready,
  output logic [1:0]          s_axil_bresp,
  output logic                s_axil_bvalid,
  input  logic                s_axil_bready,
  input  logic [7:0]          s_axil_araddr,
  input  logic                s_axil_arvalid,
  output logic                s_axil_arready,
  output logic [31:0]         s_axil_rdata,
  output logic [1:0]          s_axil_rresp,
  output logic                s_axil_rvalid,
  input  logic                s_axil_rready,
  output logic [11-1:0]       cmd_o,          // CMD (RW): register value
  output logic                cmd_wr_o,       // CMD: one-clock pulse at every software write
  output logic [32-1:0]       arg_o,          // ARG (RW): register value
  output logic                arg_wr_o,       // ARG: one-clock pulse at every software write
  input  logic [(4)*(32)-1:0] resp_i,         // RESP (RO): value read
  input  logic [8-1:0]        status_i,       // STATUS (CMD): value read
  output logic [8-1:0]        status_o,       // STATUS (CMD): data written
  output logic                status_wr_o,    // STATUS: one-clock pulse at every software write
  output logic [18-1:0]       ctrl_o,         // CTRL (RW): register value
  output logic                ctrl_wr_o,      // CTRL: one-clock pulse at every software write
  output logic [11-1:0]       blksize_o,      // BLKSIZE (RW): register value
  output logic                blksize_wr_o,   // BLKSIZE: one-clock pulse at every software write
  output logic [32-1:0]       timeout_o,      // TIMEOUT (RW): register value
  output logic                timeout_wr_o,   // TIMEOUT: one-clock pulse at every software write
  output logic [7-1:0]        irq_en_o,       // IRQ_EN (RW): register value
  output logic                irq_en_wr_o     // IRQ_EN: one-clock pulse at every software write
);
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "SDIO";
  localparam logic [31:0] IP_VERSION = "1.10";
  localparam logic [31:0] IP_DATE    = 32'h10122026;   // mm/dd/yyyy, BCD
  localparam logic [7:0] A_ID = 8'h0, A_VERSION = 8'h4, A_DATE = 8'h8;
  localparam logic [7:0] A_CMD = 8'h10;
  localparam logic [7:0] A_ARG = 8'h14;
  localparam logic [7:0] A_RESP = 8'h18;   // + 4 i, i < 4
  localparam logic [7:0] A_STATUS = 8'h28;
  localparam logic [7:0] A_CTRL = 8'h2C;
  localparam logic [7:0] A_BLKSIZE = 8'h30;
  localparam logic [7:0] A_TIMEOUT = 8'h34;
  localparam logic [7:0] A_IRQ_EN = 8'h38;
  localparam int MAP_WORDS = 15;

  logic             wr_en, rd_en, wr_err_q;
  logic [7:0]       wr_addr, rd_addr, rd_addr_q;
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  axi4_lite_slave #(
    .ADDR_W(8),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(aclk),
    .aresetn(aresetn),
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .wr_en_o(wr_en),
    .wr_addr_o(wr_addr),
    .wr_data_o(wr_data),
    .wr_strb_o(wr_strb),
    .wr_err_i(wr_err_q),
    .rd_en_o(rd_en),
    .rd_addr_o(rd_addr),
    .rd_data_i(rd_data),
    .rd_valid_i(1'b1),
    .rd_err_i(1'b0)
  );
  wire [7:0] wa = {wr_addr[7:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] cmd_q;
  logic [31:0] arg_q;
  logic [31:0] status_q;
  logic [31:0] ctrl_q;
  logic [31:0] blksize_q;
  logic [31:0] timeout_q;
  logic [31:0] irq_en_q;
  logic ro_resp;   // a write to an element of RESP
  always_comb begin
    ro_resp = 1'b0;
    for (int i = 0; i < 4; i++) if (wa == A_RESP + 8'(4 * i)) ro_resp = 1'b1;
  end
  always_ff @(posedge aclk) begin
    if (!aresetn) begin
      cmd_q <= 32'h0;
      cmd_wr_o <= 1'b0;
      arg_q <= 32'h0;
      arg_wr_o <= 1'b0;
      status_q <= '0;
      status_wr_o <= 1'b0;
      ctrl_q <= 32'h2;
      ctrl_wr_o <= 1'b0;
      blksize_q <= 32'h200;
      blksize_wr_o <= 1'b0;
      timeout_q <= 32'h186A0;
      timeout_wr_o <= 1'b0;
      irq_en_q <= 32'h0;
      irq_en_wr_o <= 1'b0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE || ro_resp);   // writes to read-only words: SLVERR
      begin
        cmd_wr_o <= wr_en && wa == A_CMD;
        if (wr_en && wa == A_CMD) cmd_q <= (cmd_q & ~wmask) | (wr_data & wmask);
      end
      begin
        arg_wr_o <= wr_en && wa == A_ARG;
        if (wr_en && wa == A_ARG) arg_q <= (arg_q & ~wmask) | (wr_data & wmask);
      end
      begin
        status_wr_o <= wr_en && wa == A_STATUS;
        if (wr_en && wa == A_STATUS) status_q <= (status_q & ~wmask) | (wr_data & wmask);
      end
      begin
        ctrl_wr_o <= wr_en && wa == A_CTRL;
        if (wr_en && wa == A_CTRL) ctrl_q <= (ctrl_q & ~wmask) | (wr_data & wmask);
      end
      begin
        blksize_wr_o <= wr_en && wa == A_BLKSIZE;
        if (wr_en && wa == A_BLKSIZE) blksize_q <= (blksize_q & ~wmask) | (wr_data & wmask);
      end
      begin
        timeout_wr_o <= wr_en && wa == A_TIMEOUT;
        if (wr_en && wa == A_TIMEOUT) timeout_q <= (timeout_q & ~wmask) | (wr_data & wmask);
      end
      begin
        irq_en_wr_o <= wr_en && wa == A_IRQ_EN;
        if (wr_en && wa == A_IRQ_EN) irq_en_q <= (irq_en_q & ~wmask) | (wr_data & wmask);
      end
    end
  end
  assign cmd_o = cmd_q[11-1:0];
  assign arg_o = arg_q[32-1:0];
  assign status_o = status_q[8-1:0];
  assign ctrl_o = ctrl_q[18-1:0];
  assign blksize_o = blksize_q[11-1:0];
  assign timeout_o = timeout_q[32-1:0];
  assign irq_en_o = irq_en_q[7-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge aclk) if (rd_en) rd_addr_q <= {rd_addr[7:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_CMD: rd_data = cmd_q;
      A_ARG: rd_data = arg_q;
      A_STATUS: rd_data = 32'(status_i);
      A_CTRL: rd_data = ctrl_q;
      A_BLKSIZE: rd_data = blksize_q;
      A_TIMEOUT: rd_data = timeout_q;
      A_IRQ_EN: rd_data = irq_en_q;
      default: begin
        for (int i = 0; i < 4; i++)
          if (rd_addr_q == A_RESP + 8'(4 * i)) rd_data = 32'(resp_i[i*(32) +: 32]);
      end
    endcase
  end
endmodule
